cat > src/lib/date.sh <<'EOF'
#!/bin/bash
# Date helpers for bookings. Dates are YYYY-MM-DD.
# check_date DATE: succeeds when DATE is a real calendar-shaped date (month 01-12, day 01-31).
check_date() {
  [[ "$1" =~ ^[0-9]{4}-[0-9]{2}-[0-9]{2}$ ]] || return 1
  local m=${1:5:2} d=${1:8:2}
  [ "$((10#$m))" -ge 1 ] && [ "$((10#$m))" -le 12 ] && [ "$((10#$d))" -ge 1 ] && [ "$((10#$d))" -le 31 ]
}
EOF
cat > src/list.sh <<'EOF'
#!/bin/bash
# list.sh [DATE]: bookings, one per line "DATE START-END ROOM WHO", sorted. src/remind.sh reads this.
set -u
. "$(dirname "$0")/lib/date.sh"
BOOKINGS=${BOOKINGS:-data/bookings.tsv}
[ -r "$BOOKINGS" ] || { echo "bookings file not found: $BOOKINGS" >&2; exit 2; }
if [ -n "${1:-}" ] && ! check_date "$1"; then echo "bad date: $1 (expected YYYY-MM-DD)" >&2; exit 2; fi
grep -v '^#' "$BOOKINGS" | awk -F'\t' -v d="${1:-}" 'NF && (d == "" || $2 == d) { printf "%s %s-%s %s %s\n", $2, $3, $4, $1, $5 }' | sort
EOF
cat > src/remind.sh <<'EOF'
#!/bin/bash
# remind.sh DATE: one reminder per booking of the day, from the listing.
set -u
. "$(dirname "$0")/lib/date.sh"
if [ -n "${1:-}" ] && ! check_date "$1"; then echo "bad date: $1 (expected YYYY-MM-DD)" >&2; exit 2; fi
out=$(bash "$(dirname "$0")/list.sh" "$@") || exit $?
[ -z "$out" ] || printf '%s\n' "$out" | while read -r d t r w; do echo "reminder to $w: $r $d $t"; done
EOF
cat > spec/list_date.spec.sh <<'EOF'
#!/bin/bash
fail=0
t=$(mktemp); printf '# room\tdate\tstart\tend\twho\naoi\t2026-01-02\t10:00\t11:00\tx\n' > "$t"
bash src/list.sh 2026/01/01 >/dev/null 2>&1; [ $? = 2 ] || { echo "a malformed date should exit 2"; fail=1; }
[ "$(bash src/list.sh 2026/01/01 2>&1 >/dev/null)" = 'bad date: 2026/01/01 (expected YYYY-MM-DD)' ] || { echo "bad date message"; fail=1; }
[ -z "$(BOOKINGS=$t bash src/list.sh 2026/01/01 2>/dev/null)" ] || { echo "a malformed date should print nothing to stdout"; fail=1; }
BOOKINGS=$t bash src/list.sh 2026-13-01 >/dev/null 2>&1; [ $? = 2 ] || { echo "month 13 should exit 2"; fail=1; }
BOOKINGS=$t bash src/list.sh 2026-01-00 >/dev/null 2>&1; [ $? = 2 ] || { echo "day 00 should exit 2"; fail=1; }
[ "$(BOOKINGS=$t bash src/list.sh 2026-01-02 2>/dev/null)" = '2026-01-02 10:00-11:00 aoi x' ] || { echo "a well-formed date should pass"; fail=1; }
rm -f "$t"; exit $fail
EOF
cat > spec/remind_date.spec.sh <<'EOF'
#!/bin/bash
fail=0
t=$(mktemp); printf '# room\tdate\tstart\tend\twho\naoi\t2026-01-02\t10:00\t11:00\tx\n' > "$t"
BOOKINGS=$t bash src/remind.sh 2026/01/02 >/dev/null 2>&1; [ $? = 2 ] || { echo "remind: a malformed date should exit 2"; fail=1; }
[ "$(BOOKINGS=$t bash src/remind.sh 2026/01/02 2>&1 >/dev/null)" = 'bad date: 2026/01/02 (expected YYYY-MM-DD)' ] || { echo "remind: bad date message"; fail=1; }
[ "$(BOOKINGS=$t bash src/remind.sh 2026-01-02)" = 'reminder to x: aoi 2026-01-02 10:00' ] || { echo "remind: a well-formed date should remind"; fail=1; }
rm -f "$t"; exit $fail
EOF
bash src/remind.sh 2026-01-02 2>&1 | head -2; bash tools/check; echo rc=$?; bash tools/lint; echo lint=$?

